package dev.beforesun.atvvprobe;
import android.app.*; import android.os.*; import android.Manifest; import android.content.pm.PackageManager; import android.bluetooth.*; import android.util.Log; import android.widget.*; import java.util.*;
public class MainActivity extends Activity {
 static final String TAG="ATVV_PROBE"; static final String SUFFIX="-5a21-4f05-bc7d-af01f617b664";
 TextView text; BluetoothGatt gatt; BluetoothGattCharacteristic tx,rx,ctl; int frames=0, bytes=0; int nonzero=0; boolean started=false;
 void say(String s){Log.i(TAG,s);runOnUiThread(()->text.append("\n"+s));}
 UUID id(int n){return UUID.fromString(String.format(Locale.US,"ab5e%04x",n)+SUFFIX);}
 @Override public void onCreate(Bundle b){super.onCreate(b);text=new TextView(this);text.setTextSize(21);text.setPadding(30,25,30,25);text.setText("Remote Mic Probe");ScrollView v=new ScrollView(this);v.addView(text);setContentView(v); if(checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.BLUETOOTH_CONNECT},1);}else scan();}
 @Override public void onRequestPermissionsResult(int c,String[] p,int[] r){super.onRequestPermissionsResult(c,p,r);if(r.length>0&&r[0]==0)scan();else say("Bluetooth permission denied");}
 void scan(){BluetoothAdapter a=BluetoothAdapter.getDefaultAdapter(); if(a==null){say("No Bluetooth adapter");return;}for(BluetoothDevice d:a.getBondedDevices()){say("Bonded: "+d.getName()+" type="+d.getType());if(d.getName()!=null&&d.getName().contains("Chromecast Remote")){say("Connecting to "+d.getName());gatt=d.connectGatt(this,false,callback,BluetoothDevice.TRANSPORT_LE);break;}}}
 BluetoothGattCallback callback=new BluetoothGattCallback(){
 @Override public void onConnectionStateChange(BluetoothGatt g,int status,int state){say("Connection status="+status+" state="+state);if(status==0&&state==BluetoothProfile.STATE_CONNECTED){g.discoverServices();}}
 @Override public void onServicesDiscovered(BluetoothGatt g,int status){say("Services status="+status+" count="+g.getServices().size());for(BluetoothGattService s:g.getServices()){say("Service: "+s.getUuid());}BluetoothGattService s=g.getService(id(1));if(s==null){say("ATVV SERVICE NOT FOUND");return;}say("ATVV SERVICE FOUND");tx=s.getCharacteristic(id(2));rx=s.getCharacteristic(id(3));ctl=s.getCharacteristic(id(4));say("TX="+(tx!=null)+" RX="+(rx!=null)+" CTL="+(ctl!=null));if(tx==null||rx==null||ctl==null)return;g.setCharacteristicNotification(ctl,true);BluetoothGattDescriptor cccd=ctl.getDescriptor(UUID.fromString("00002902-0000-1000-8000-00805f9b34fb"));if(cccd==null){say("No CTL CCCD");return;}cccd.setValue(BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE);say("Enable CTL notification="+g.writeDescriptor(cccd));}
 @Override public void onDescriptorWrite(BluetoothGatt g,BluetoothGattDescriptor d,int status){say("Descriptor "+d.getCharacteristic().getUuid()+" status="+status);if(status!=0)return;if(d.getCharacteristic().getUuid().equals(id(4))){g.setCharacteristicNotification(rx,true);BluetoothGattDescriptor cccd=rx.getDescriptor(UUID.fromString("00002902-0000-1000-8000-00805f9b34fb"));if(cccd==null){say("No RX CCCD");return;}cccd.setValue(BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE);g.writeDescriptor(cccd);}else if(!started){started=true;send(g,new byte[]{0x0a,0x00,0x01,0x00,0x01});}}
 @Override public void onCharacteristicWrite(BluetoothGatt g,BluetoothGattCharacteristic c,int status){say("Write "+hex(c.getValue())+" status="+status);if(status==0&&c.getValue()!=null&&c.getValue().length>0&&c.getValue()[0]==0x0a){new Handler(getMainLooper()).postDelayed(()->send(g,new byte[]{0x0c,0x00,0x01}),500);}}
 @Override public void onCharacteristicChanged(BluetoothGatt g,BluetoothGattCharacteristic c){byte[] b=c.getValue();if(c.getUuid().equals(id(4)))say("CTL "+hex(b));else{frames++;bytes+=b.length;for(byte x:b)if(x!=0)nonzero++;if(frames%25==1)say("AUDIO frames="+frames+" bytes="+bytes+" nonzero="+nonzero+" first="+hex(Arrays.copyOf(b,Math.min(12,b.length))));}}
 };
 void send(BluetoothGatt g,byte[] b){tx.setWriteType(BluetoothGattCharacteristic.WRITE_TYPE_DEFAULT);tx.setValue(b);say("Send "+hex(b)+" queued="+g.writeCharacteristic(tx));}
 String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format(Locale.US,"%02x ",x&255));return s.toString();}
 @Override protected void onDestroy(){if(gatt!=null)gatt.close();super.onDestroy();}
}
